/* Standalone design prototype. All operations are simulated in browser memory.
   No API calls, real server controls, uploads, or account changes. */
const main = document.querySelector('main');
const dialog = document.querySelector('#dialog');
const storageKey = 'pitlane-concept-v1';
const tracks = {
  rudskogen: {name:'Rudskogen', country:'Norway', detail:'Technical corners. Familiar company.', image:'rudskogen.png', capacity:16},
  ebisu: {name:'Ebisu Minami', country:'Japan', detail:'The home of sideways.', image:'ebisu.png', capacity:24},
  playground: {name:'Drift Playground', country:'Japan', detail:'A small track with a big personality.', image:'playground.png', capacity:12},
};
const initialState = () => ({
  sessions:[
    {id:'club',name:'Thursday drift club',track:'rudskogen',type:'Drift',cars:'Club drift cars',duration:60,grid:12,weather:'Late afternoon',rules:'Friendly',status:'live',server:'Club 01',people:6,when:'18:00',highlights:3},
    {id:'ebisu',name:'An evening at Ebisu',track:'ebisu',type:'Drift',cars:'Club drift cars',duration:60,grid:12,weather:'Late afternoon',rules:'Friendly',status:'planned',server:'Club 02',people:0,when:'20:00',date:'2026-09-10T20:00',highlights:0},
    {id:'sunday',name:'Sunday, sideways',track:'playground',type:'Drift',cars:'Club drift cars',duration:60,grid:12,weather:'Clear midday',rules:'Friendly',status:'finished',server:'Club 01',people:6,when:'Sun, 6 Sep',highlights:5},
    {id:'laps',name:'Just one more lap',track:'rudskogen',type:'Practice',cars:'Road cars',duration:45,grid:10,weather:'Clear midday',rules:'Factory assists',status:'finished',server:'Club 02',people:4,when:'Sat, 5 Sep',highlights:0},
  ],
  drivers:[
    {id:'nora',name:'Nora Hansen',initials:'NH',car:'Nissan Silvia S14',score:24680,lap:'1:38.420',visits:14,guest:false,live:true},
    {id:'jonas',name:'Jonas Berg',initials:'JB',car:'BMW E36',score:21340,lap:'1:39.860',visits:22,guest:false,live:true},
    {id:'mia',name:'Mia Solberg',initials:'MS',car:'Nissan 180SX',score:19820,lap:'1:40.105',visits:9,guest:true,live:true},
    {id:'erik',name:'Erik Lund',initials:'EL',car:'Nissan Silvia S14',score:17650,lap:'1:41.210',visits:18,guest:false,live:true},
    {id:'sara',name:'Sara Dahl',initials:'SD',car:'BMW E36',score:16210,lap:'1:42.085',visits:6,guest:true,live:true},
    {id:'leo',name:'Leo Strand',initials:'LS',car:'Toyota Soarer',score:14890,lap:'1:43.712',visits:12,guest:false,live:true},
    {id:'alex',name:'Alex Nilsen',initials:'AN',car:'Nissan Silvia S14',score:12840,lap:'1:44.930',visits:3,guest:true,live:false},
  ],
  seat:'nora', saved:false, imported:false, onboarding:false, tab:'timing', sessionFilter:'all', query:'', feed:[], phase:'Practice', demoIndex:0,
});
let state;
try {state = JSON.parse(sessionStorage.getItem(storageKey)) || initialState();} catch {state = initialState();}
let draft;
try {draft=JSON.parse(sessionStorage.getItem(storageKey+'-draft')) || null;} catch {draft=null;}
let toastTimer;
let dialogOrigin = null;
const e = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = number => Number(number).toLocaleString('en-GB');
const track = s => tracks[s?.track] || tracks.rudskogen;
const asset = name => `assets/${name}`;
const icons = {
  plus:'M12 5v14M5 12h14', arrow:'M5 12h14m-5-5 5 5-5 5', back:'M19 12H5m5-5-5 5 5 5', check:'m5 12 4 4 10-10',
  play:'m9 5 11 7-11 7Z', flag:'M5 21V4m0 0c5-4 9 4 14 0v9c-5 4-9-4-14 0',
  road:'M6 3 3 21M18 3l3 18M12 3v4m0 4v3m0 4v3', car:'m5 7 2-3h10l2 3M3 11l2-4h14l2 4v7H3ZM7 18v2m10-2v2M6 12h2m8 0h2',
  sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5.5 5.5 7 7m10 10 1.5 1.5M5.5 18.5 7 17m10-10 1.5-1.5M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
  clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0', sliders:'M4 7h6m4 0h6M4 17h10m4 0h2M10 4v6m4 4v6',
  people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M18 3a4 4 0 0 1 0 8m4 10v-2a4 4 0 0 0-3-4',
  screen:'M3 3h18v14H3ZM8 21h8m-4-4v4', camera:'M3 7h4l2-3h6l2 3h4v13H3ZM16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',
  search:'m20 20-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0', repeat:'M3 10V6h15l-3-3m6 11v4H6l3 3M3 6l4 4m14 8-4-4',
  info:'M12 10v6m0-10v.1M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0', trophy:'M7 3h10v7a5 5 0 0 1-10 0ZM7 5H3v3a4 4 0 0 0 4 4m10-7h4v3a4 4 0 0 1-4 4M12 15v6m-4 0h8',
  link:'m10 13 4-4M9 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0m3 1 2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0',
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name] || icons.arrow}"/></svg>`;
const btn = (label,action,value='',kind='') => `<button class="button ${kind}" data-action="${action}" data-value="${e(value)}">${label}</button>`;
const linkBtn = (label,to,kind='') => `<a class="button ${kind}" href="#${to}">${label}</a>`;
const person = id => state.drivers.find(d => d.id === id) || state.drivers[0];
const badge = s => s.status === 'live' ? '<span class="badge live"><span class="status-dot"></span>On track</span>' : `<span class="badge ${s.status==='planned'?'warm':''}">${s.status==='planned'?'Coming up':'Finished'}</span>`;
function avatar(d,big=false){return `<span class="avatar ${d.guest?'rose':''} ${big?'big':''}">${e(d.initials)}</span>`;}
function heading(title,sub='',actions='',eyebrow=''){return `<div class="page-heading"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function remember(){try{sessionStorage.setItem(storageKey,JSON.stringify(state));sessionStorage.setItem(storageKey+'-draft',JSON.stringify(draft));}catch{/* The mock still works without storage. */}}
function go(route){if(location.hash===`#${route}`)render();else location.hash=route;}
function toast(message){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');toastTimer=setTimeout(()=>el.classList.remove('visible'),4500);}
function modal(title,body){dialogOrigin=document.activeElement;document.querySelector('#dialog-content').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="close-button" data-action="close" aria-label="Close dialog">×</button></div><div class="dialog-body">${body}</div>`;if(!dialog.open)dialog.showModal();}
function close(){dialog.close();if(dialogOrigin?.isConnected)dialogOrigin.focus();}
function findSession(id){return state.sessions.find(s=>s.id===id);}
function repeatItem(s){return `<div class="repeat-item"><img src="${asset(track(s).image)}" alt="${e(track(s).name)}"><div><h3>${e(s.name)}</h3><p class="small">${e(track(s).name)} · ${s.duration} min · ${e(s.type)}</p></div>${btn('Use again '+icon('repeat'),'reuse',s.id,'compact')}</div>`;}
function moment(){return `<button class="moment" data-action="highlight" aria-label="Preview Nora's personal best highlight"><div class="moment-image"><img src="${asset('silvia.jpg')}" alt="Nissan Silvia car preview"><div class="moment-play"><span>${icon('play')}</span></div><span class="badge glass" style="position:absolute;bottom:12px;left:12px">Highlight preview</span></div><div class="moment-caption"><b>Nora found her flow.</b><span>24,680 pts ↗</span></div></button>`;}
function today(){
  const live=state.sessions.filter(s=>s.status==='live');const next=state.sessions.find(s=>s.status==='planned');
  if(state.onboarding && !state.sessions.length)return welcome();
  return `${heading('Tonight, we drive<span class="accent">.</span>','A little less organizing. A lot more time on track.',linkBtn(icon('screen')+' Live streams','streams')+linkBtn(icon('plus')+' New session','new','primary'),'THURSDAY, 10 SEPTEMBER · NORTHSIDE CLUB')}
  <div class="today-grid">
    ${live.length?live.slice(0,1).map(s=>`<article class="session-hero"><img class="hero-image" src="${asset(track(s).image)}" alt="${e(track(s).name)} circuit"><div class="hero-top"><span class="badge glass"><span class="status-dot"></span>ON TRACK NOW</span><span class="badge glass">${e(s.server)} · ${s.id==='club'?'42 min in':'Just started'}</span></div><div><div class="eyebrow" style="color:#e5e9df">${e(track(s).name)} / ${e(track(s).country)}</div><h2 class="hero-title">${e(s.name)}</h2><div class="hero-bottom"><div><p class="small">${s.type==='Drift'?'Open drifting. Make yourself at home.':s.type==='Race'?'The grid is ready. Make it a good one.':'Settle in. Find your next personal best.'}</p><div class="hero-meta"><span class="row" style="gap:7px"><span class="avatars"><span>NH</span><span>JB</span><span>MS</span></span>${s.people} ${s.people===1?'driver':'drivers'}</span><span>${icon('camera')} ${s.highlights} highlights saved</span></div></div>${linkBtn('Open session '+icon('arrow'),'live/'+s.id,'white')}</div></div></article>`).join(''):`<article class="session-hero"><img class="hero-image" src="${asset('rudskogen.png')}" alt="An empty Rudskogen circuit"><div class="badge glass" style="align-self:flex-start">ALL CLEAR</div><div><h2 class="hero-title">The track is yours.</h2><p style="margin:12px 0 20px">Pick a session. We’ll take care of the setup.</p>${linkBtn('Let’s drive '+icon('arrow'),'new','white')}</div></article>`}
    ${next?`<article class="schedule-card"><div class="row between"><span class="eyebrow muted">Later tonight</span><span class="badge">Scheduled</span></div><img class="schedule-photo" src="${asset(track(next).image)}" alt="${e(track(next).name)}"><div class="schedule-time num">${e(next.when)}<span>${next.date?.slice(0,10)==='2026-09-10'?'Today · Oslo':e(next.date?.slice(0,10)||'Next')}</span></div><div class="schedule-details"><h3>${e(next.name)}</h3><p class="small">${e(track(next).name)} · ${next.duration} min ${e(next.type.toLowerCase())}</p></div><button class="text-button" data-action="planned" data-value="${next.id}">Ready when you are ${icon('arrow')}</button></article>`:`<article class="schedule-card"><span class="eyebrow muted">Keep a good thing going</span><img class="schedule-photo" src="${asset('ebisu.png')}" alt="Ebisu Minami"><h3>Where to next?</h3><p class="small">Line up another track. We’ll handle the changeover.</p>${linkBtn('Plan a session '+icon('arrow'),'new')}</article>`}
  </div>
  <div class="quiet-row"><span>${icon('check')} ${live.length} ${live.length===1?'session':'sessions'} running smoothly</span><span>Results saved as you drive</span><span>${2-live.length} of 2 servers free ${icon('arrow')}</span></div>
  ${live.length>1?live.slice(1).map(s=>`<div class="live-banner"><div>${badge(s)}<h3 style="margin-top:9px">${e(s.name)}</h3><p class="small">${e(track(s).name)} · ${e(s.server)}</p></div>${linkBtn('Open session '+icon('arrow'),'live/'+s.id)}</div>`).join(''):''}
  <div class="bottom-grid"><section><div class="section-heading"><h2>Good enough to do again.</h2><a class="text-button" href="#sessions">All sessions ${icon('arrow')}</a></div><div class="repeat-list">${state.sessions.filter(s=>s.status==='finished').slice(0,2).map(repeatItem).join('')||'<p class="small">Your sessions will be here, ready for another go.</p>'}</div></section><section><div class="section-heading"><h2>A moment worth keeping.</h2><span class="eyebrow muted">Auto-saved</span></div>${moment()}</section></div>`;
}
function newSession(){return `<a class="back" href="#today">${icon('back')} Back to today</a><div class="center-heading"><div class="eyebrow">LET’S MAKE A SESSION</div><h1>What sounds good?</h1><p>Choose the driving. We’ll sort out the rest.</p></div><div class="experience-grid">${[
  ['Drift','01','playground.png','Find your flow.','Open track, drift scoring, and automatic highlights.','Relaxed rules · 60 minutes'],
  ['Race','02','rudskogen.png','A little friendly rivalry.','Practice, qualifying, then a proper race together.','Fair grid · 45 minutes'],
  ['Practice','03','ebisu.png','Just you and the next lap.','An open track, your favourite car, and room to improve.','Factory assists · 45 minutes'],
].map(([type,num,img,title,body,meta])=>`<button class="experience" data-action="experience" data-value="${type}"><div class="experience-art"><img src="${asset(img)}" alt=""><span class="art-number">${num}</span></div><div class="experience-body"><h2>${type}</h2><p><strong style="font-weight:550;color:var(--ink)">${title}</strong><br>${body}</p><div class="row">${meta}${icon('arrow')}</div></div></button>`).join('')}</div><p class="quiet-note">Already have a favourite? <a class="text-button" href="#sessions">Use a previous session ${icon('arrow')}</a></p>`;}
function makeDraft(type='Drift',source){draft=source?{...source,name:source.name+' · again'}:{name:type==='Drift'?'An evening, sideways':type==='Race'?'A little friendly rivalry':'Just one more lap',type,track:'rudskogen',cars:type==='Drift'?'Club drift cars':type==='Race'?'BMW M3 Cup':'Road cars',duration:type==='Drift'?60:45,grid:12,weather:'Late afternoon',rules:type==='Drift'?'Friendly':'Factory assists'};Object.assign(draft,{when:'now',date:'2026-09-11T19:00',capture:draft.type==='Drift',repeat:false});go('build');}
function ready(){
  if(!draft)return {ok:false,message:'Choose an experience first.'};
  if(!draft.name.trim())return {ok:false,message:'Give this session a name.'};
  if(draft.grid>track(draft).capacity)return {ok:false,message:`${track(draft).name} has ${track(draft).capacity} spaces. Reduce the grid or choose a larger track.`};
  const servers=['Club 01','Club 02'];
  if(draft.when==='next')return {ok:true,server:state.sessions.find(s=>s.status==='live')?.server||'Club 01',message:'Starts when the current session finishes.'};
  const start=draft.when==='later'?new Date(draft.date).getTime():new Date('2026-09-10T18:42').getTime();
  if(!Number.isFinite(start)||start<new Date('2026-09-10T18:42').getTime())return {ok:false,message:'Choose a future date and time. The demo clock is 10 Sep, 18:42.'};
  const end=start+Number(draft.duration)*60000;
  const server=servers.find(name=>!state.sessions.some(s=>{
    if(s.server!==name||s.status==='finished')return false;
    const begin=s.status==='live'?new Date('2026-09-10T18:00').getTime():new Date(s.date||'2026-09-10T19:00').getTime();
    const finish=s.status==='live'?(s.id==='club'?new Date('2026-09-10T19:00').getTime():new Date('2026-09-10T18:42').getTime()+s.duration*60000):begin+s.duration*60000;
    return start<finish&&end>begin;
  }));
  if(!server)return {ok:false,message:'Both servers are occupied for part of this session. Choose Later or After current.'};
  return {ok:true,server,message:draft.when==='later'?'We’ll start the session at your chosen time.':'A free server is ready for this exact session.'};
}
function setting(label,value,note,kind,ic){return `<div class="setting-line"><span class="setting-icon">${icon(ic)}</span><div class="setting-content"><span>${label}</span><b>${e(value)}</b><small>${e(note)}</small></div><button class="text-button" data-action="edit" data-value="${kind}" aria-label="Change ${label.toLowerCase()}">Change</button></div>`;}
function build(){if(!draft)return newSession();const r=ready();return `<a class="back" href="#new">${icon('back')} Choose a different experience</a>${heading('Ready when you are.','Keep the defaults, or make it yours.',`<span class="small ${r.ok?'green':'accent'}">${icon(r.ok?'check':'info')} ${r.ok?'All checked':'Check your setup'}</span><button class="button primary" data-action="launch" ${r.ok?'':'disabled'}>${draft.when==='now'?'Start session':draft.when==='later'?'Schedule session':'Add after current'} ${icon('arrow')}</button>`,'YOUR '+e(draft.type.toUpperCase())+' SESSION')}<div class="builder-grid"><section>
  ${setting('Track',track(draft).name,track(draft).country+' · '+track(draft).capacity+' grid spaces','track','road')}
  ${setting('Cars',draft.cars,draft.grid+' spaces · Liveries assigned for you','cars','car')}
  ${setting('Format',draft.type==='Race'?'Practice → qualify → race':draft.type==='Drift'?'Open drifting':'Open practice',draft.duration+' minutes · '+(draft.type==='Drift'?'Drift scoring included':'Lap timing included'),'format','clock')}
  ${setting('Conditions',draft.weather,draft.weather==='Late afternoon'?'Clear sky · 22°C · 16:00':'Clear sky · 21°C · 12:00','weather','sun')}
  ${setting('Driving rules',draft.rules,draft.rules==='Friendly'?'Forgiving damage. Easy to get back out.':'Factory assists. Predictable grip.','rules','sliders')}
  <details class="advanced"><summary>Fine-tune the details</summary><label class="field">Session name<input data-draft="name" value="${e(draft.name)}" maxlength="70"></label><label class="toggle-line"><span>Save drift highlights automatically<small>Needs a connected recording source. All demo sources are ready.</small></span><input type="checkbox" data-draft="capture" ${draft.capture?'checked':''}></label><p class="small muted">Each session owns its settings. Changing this one won’t change your other sessions.</p></details>
  <div class="notice">This whole combination is saved with your session, ready to use again.</div>
  </section><aside class="builder-summary"><img src="${asset(track(draft).image)}" alt="${e(track(draft).name)}"><div class="summary-body"><span class="eyebrow muted">YOUR SESSION AT A GLANCE</span><h2>${e(draft.name)}</h2><p>${e(track(draft).name)} · ${e(draft.type)} · ${draft.duration} minutes</p><hr><div class="eyebrow muted" style="margin-bottom:12px">When do we drive?</div><div class="segmented" aria-label="Session start"><button data-action="when" data-value="now" aria-pressed="${draft.when==='now'}">Now</button><button data-action="when" data-value="later" aria-pressed="${draft.when==='later'}">Later</button><button data-action="when" data-value="next" aria-pressed="${draft.when==='next'}">After current</button></div>${draft.when==='later'?`<label class="field">Start time · Europe/Oslo<input type="datetime-local" data-draft="date" value="${e(draft.date)}" min="2026-09-10T18:43" required></label>`:''}<div class="summary-label"><span>Server</span><b>${r.server?e(r.server)+(draft.when==='next'?' · next in line':' · chosen for you'):'Waiting for a free slot'}</b></div><div class="summary-label"><span>Grid</span><b>${draft.grid} / ${track(draft).capacity} spaces</b></div><div class="summary-label"><span>Results</span><b>Saved automatically</b></div><div id="readiness" class="readiness ${r.ok?'':'blocked'}" role="status"><div class="row">${icon(r.ok?'check':'info')}${r.ok?'Everything is ready': 'One thing to sort out'}</div><p>${e(r.message)}</p></div><p class="quiet-note" style="margin:14px 0 0;text-align:center;font-size:11px">${draft.when==='now'?'Starts this session. Your other session keeps running.':draft.when==='next'?'The current session finishes first.':'We’ll remember the time. You don’t have to be here.'}</p></div></aside></div>`;}
function sessionDrivers(s){return s.status==='finished' ? (s.results || initialState().drivers.slice(0,s.people)) : state.drivers.filter(d=>d.live&&(d.session||'club')===s.id);}
function timing(s){const drift=s.type==='Drift';const rows=sessionDrivers(s);return `<table class="timing"><caption class="sr-only">${drift?'Drift scores':'Lap times'} for this simulated session</caption><thead><tr><th scope="col">#</th><th scope="col">Driver</th><th scope="col">${drift?'Best run':'Best lap'}</th><th scope="col">${drift?'Last run':'Gap'}</th></tr></thead><tbody>${rows.map((d,i)=>`<tr><td class="position num">${i+1}</td><td><button class="person-button row" data-action="profile" data-value="${d.id}">${avatar(d)}<span><span class="name">${e(d.name)}${d.id===state.seat?' <span class="badge" style="font-size:9px">Rig 01</span>':''}</span><span class="car">${e(d.car)}</span></span></button></td><td class="num">${drift?fmt(d.score):e(d.lap)}</td><td class="num muted">${drift?fmt(Math.round(d.score*.87)):i?'+'+(i*1.37).toFixed(3):'Leader'}</td></tr>`).join('')||'<tr><td colspan="4">Waiting for the first driver. Invite your friends to join.</td></tr>'}</tbody></table>`;}
function live(id){const s=findSession(id);if(!s)return missing();if(s.status==='finished')return recap(id);const d=person(state.seat);return `${heading(e(s.name),e(track(s).name)+' · '+e(s.cars),badge(s)+linkBtn(icon('screen')+' Watch','watch/'+s.id),'YOUR SESSION / '+e(s.server))}
  <div class="live-banner"><div><b style="font-weight:550">${s.type==='Drift'?'Open drifting':s.type==='Race'?e(state.phase):'Open practice'}</b><p class="small">${s.type==='Race'?'Practice → qualifying → race':'Plenty of room to find your rhythm.'}</p></div><div class="session-progress"><div class="row between"><span>${s.id==='club'?'42:00':'00:00'} elapsed</span><span class="muted">${s.id==='club'?'18:00':s.duration+':00'} remaining</span></div><div class="track-progress" role="progressbar" aria-label="Session elapsed" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${s.id==='club'?70:0}"><span style="width:${s.id==='club'?70:0}%"></span></div></div>${btn(icon('link')+' Invite drivers','invite',s.id)}</div>
  <div class="live-layout"><section><details class="circuit-preview"><summary><span class="row">${icon('road')} ${e(track(s).name)}<span class="small muted">${e(s.weather)} · 22°C</span></span><span class="small">View circuit</span></summary><div class="session-hero live-visual"><img class="hero-image" src="${asset(track(s).image)}" alt="${e(track(s).name)}"><div class="hero-top"><span class="badge glass">${s.people} drivers on track</span><span class="badge glass">${e(s.weather)} · 22°C</span></div>${s.track==='rudskogen'?`<img class="outline" src="${asset('outline.png')}" alt="Rudskogen circuit outline">`:''}<div class="hero-bottom"><div><div class="eyebrow">${e(track(s).country)}</div><h2 class="hero-title">${e(track(s).name)}</h2></div>${btn('Change for next time','reuse',s.id,'light compact')}</div></div></details><div class="live-tabs" aria-label="Session information"><button data-action="live-tab" data-value="timing" aria-pressed="${state.tab==='timing'}">${s.type==='Drift'?'Drift board':'Live timing'}</button><button data-action="live-tab" data-value="moments" aria-pressed="${state.tab==='moments'}">Highlights <span class="muted">${s.highlights}</span></button><button data-action="live-tab" data-value="activity" aria-pressed="${state.tab==='activity'}">Activity</button></div>${state.tab==='timing'?timing(s):state.tab==='moments'?`<div class="section-heading"><h3>The good bits, kept.</h3><span class="small muted">Saved automatically</span></div>${moment()}`:`${state.feed.map(x=>`<div class="activity-item"><time>Now</time><div>${e(x)}</div></div>`).join('')}<div class="activity-item"><time>18:40</time><div>Nora set a new personal best.<p>24,680 points · Highlight saved automatically.</p></div></div><div class="activity-item"><time>18:34</time><div>Mia joined the session.<p>Nissan 180SX · Ready to drive.</p></div></div><div class="activity-item"><time>18:00</time><div>The session started.<p>Settings checked. Grid ready.</p></div></div>`}</section>
  <aside>${s.people===0?`<div class="control-panel"><h3>Ready for your first driver.</h3><p class="small">The session is running. Invite someone and their timing will appear here.</p>${btn(icon('link')+' Invite drivers','invite',s.id,'full')}</div>`:`<div class="control-panel"><h3>Who’s at the wheel?</h3><p class="small">Sharing a simulator? Keep every score with the right person.</p><div class="eyebrow">RIG 01 / NISSAN SILVIA S14</div><div class="handover">${avatar(d)}<div><b>${e(d.name)}</b><small>Scores and highlights belong to ${e(d.name.split(' ')[0])}</small></div></div>${btn(icon('people')+' Next driver','handover',s.id,'full')}<div class="control-section"><div class="row between"><b class="small">Highlights</b><span class="badge live">${s.type==='Drift'?'Auto-saving':'Lap history on'}</span></div><p class="small" style="margin-top:9px">${s.type==='Drift'?'Great drift runs become clips, filed under the driver.':'Every lap stays with its driver, ready to compare later.'}</p></div></div>`}
  <div class="control-panel" style="margin-top:20px"><h3>A little help from the pit.</h3><button class="text-button" data-action="message" data-value="${s.id}">Message the drivers ${icon('arrow')}</button>${s.type==='Race'?`<div class="control-section"><button class="text-button" data-action="phase" data-value="${s.id}">Move to ${state.phase==='Practice'?'qualifying':'race'} ${icon('arrow')}</button></div>`:''}<div class="control-section"><button class="text-button" data-action="manage-drivers" data-value="${s.id}">Manage drivers ${icon('arrow')}</button><button class="text-button" data-action="end" data-value="${s.id}">Finish session ${icon('flag')}</button></div></div><p class="notice">Changes to the next session stay separate from what’s running now.</p></aside></div>`;}
function sessionCard(s){return `<article class="session-card"><img src="${asset(track(s).image)}" alt="${e(track(s).name)}"><div class="session-card-content">${badge(s)}<h3>${e(s.name)}</h3><p>${e(track(s).name)} · ${e(s.type)} · ${s.duration} min</p><div class="session-card-footer"><span>${e(s.when)}${s.status==='finished'?` · ${s.people} drivers`:''}</span>${s.status==='live'?linkBtn('Open '+icon('arrow'),'live/'+s.id,'compact'):s.status==='planned'?btn('View '+icon('arrow'),'planned',s.id,'compact'):linkBtn('Recap '+icon('arrow'),'recap/'+s.id,'compact')}</div></div></article>`;}
function sessions(){let list=state.sessions.filter(s=>(state.sessionFilter==='all'||s.status===state.sessionFilter)&&`${s.name} ${track(s).name} ${s.type}`.toLowerCase().includes(state.query.toLowerCase()));return `${heading('Every drive has a home.','Plan the next one. Relive the last one. Repeat a favourite.',linkBtn(icon('plus')+' New session','new','primary'),'YOUR SESSIONS')}<div class="filter-bar"><div class="segmented" aria-label="Filter sessions">${[['all','All sessions'],['planned','Upcoming'],['finished','Finished']].map(([id,label])=>`<button data-action="filter" data-value="${id}" aria-pressed="${state.sessionFilter===id}">${label}</button>`).join('')}</div><label class="search">${icon('search')}<span class="sr-only">Search sessions</span><input id="session-search" placeholder="Find a session or track" value="${e(state.query)}" data-search="sessions"></label></div><div class="card-grid" id="session-results">${list.map(sessionCard).join('')||'<div class="empty"><h2>No sessions here yet.</h2><p>Try a different search, or create your next drive.</p>'+linkBtn('New session','new','primary')+'</div>'}</div>`;}
function drivers(){return `${heading('The people make it.','One profile per person. Every lap, drift, and good moment together.',btn(icon('plus')+' Add a driver','add-driver','','primary'),'YOUR DRIVERS')}<div class="filter-bar"><span class="small muted">${state.drivers.length} people in your club · ${state.drivers.filter(d=>d.live).length} on track</span><label class="search">${icon('search')}<span class="sr-only">Search drivers</span><input id="driver-search" placeholder="Find a driver" data-search="drivers"></label></div><div id="driver-results">${driverRows(state.drivers)}</div><p class="notice">Steam accounts and shared simulators connect to people here. Nobody needs a second kind of profile.</p>`;}
function driverRows(ds){return ds.map(d=>`<div class="driver-row">${avatar(d)}<div class="driver-info"><h3><a href="#driver/${d.id}">${e(d.name)}</a></h3><p class="small">${d.live?'On track now':'Last drove Sunday'}${d.guest?' · Shares a simulator':''}</p></div><div class="driver-stat num">${fmt(d.score)}<small>Personal best · drift points</small></div><div class="driver-stat num">${d.visits}<small>Sessions together</small></div><a class="text-button" href="#driver/${d.id}">Profile ${icon('arrow')}</a></div>`).join('')||'<div class="empty"><h2>No matching drivers.</h2><p>Try another name.</p></div>';}
function profile(id){const d=person(id);return `<a class="back" href="#drivers">${icon('back')} Everyone at the club</a><div class="driver-profile-header">${avatar(d,true)}<div><span class="eyebrow muted">${d.live?'ON TRACK NOW':'ONE OF THE REGULARS'}</span><h1>${e(d.name)}</h1><p>${d.guest?'Shared simulator driver':'Connected through Assetto Corsa'} · Part of the club since June</p></div></div><div class="recap-metrics"><div><b class="num">${fmt(d.score)}</b><span>Best drift · ${e(track(state.sessions[0]).name)}</span></div><div><b class="num">${e(d.lap)}</b><span>Best lap · Rudskogen</span></div><div><b class="num">${d.visits}</b><span>Sessions with the club</span></div></div><div class="bottom-grid"><section><div class="section-heading"><h2>Recent drives</h2></div>${state.sessions.filter(s=>s.status==='finished').map(s=>`<div class="repeat-item"><img src="${asset(track(s).image)}" alt="${e(track(s).name)}"><div><h3>${e(s.name)}</h3><p class="small">${e(s.when)} · ${e(s.type)}</p></div>${linkBtn('Recap '+icon('arrow'),'recap/'+s.id,'compact')}</div>`).join('')}</section><section><div class="section-heading"><h2>Personal highlights</h2></div>${watchState().captures.some(c=>c.driver===id)?`<button class="button" data-watch-action="driver-captures" data-value="${e(id)}" style="margin-bottom:20px">${icon('camera')} Saved simulator moments (${watchState().captures.filter(c=>c.driver===id).length})</button>`:''}${id==='nora'?moment():`<div class="empty" style="padding:35px 10px"><h3>The next good moment is out there.</h3><p class="small" style="margin-top:12px">Clips will appear here when ${e(d.name.split(' ')[0])} has a recording source and lands a great run.</p></div>`}</section></div>`;}
function recap(id){const s=findSession(id);if(!s)return missing();return `<a class="back" href="#sessions">${icon('back')} All sessions</a>${heading('That was a good one.','Your results are already saved. The next drive is one click away.',btn(icon('repeat')+' Run it again','reuse',s.id,'primary'),'SESSION RECAP')}<div class="session-hero recap-hero"><img class="hero-image" src="${asset(track(s).image)}" alt="${e(track(s).name)}"><div class="hero-top"><span class="badge glass">FINISHED · ${e(s.when)}</span><span class="badge glass">${e(s.type)}</span></div><div><h2 class="hero-title">${e(s.name)}</h2><p>${e(track(s).name)} · ${e(s.cars)}</p></div></div><div class="recap-metrics"><div><b class="num">${s.people}</b><span>Drivers together</span></div><div><b class="num">${s.duration}<span style="font-size:18px"> min</span></b><span>Well spent on track</span></div><div><b class="num">${s.highlights}</b><span>Highlights kept automatically</span></div></div><div class="bottom-grid"><section><div class="section-heading"><h2>${s.type==='Drift'?'The drift board':'The lap board'}</h2><span class="small muted">This session</span></div>${timing(s)}</section><section><div class="section-heading"><h2>Pick of the session</h2></div>${s.highlights?moment():'<p class="small">No clips captured this time. Every lap is still in the driver history.</p>'}<button class="text-button" data-action="export" data-value="${s.id}" style="margin-top:18px">Export results ${icon('arrow')}</button></section></div>`;}
function garage(){return `${heading('Everything behind a good drive.','Set it up once. Come back when something needs attention.','','THE GARAGE')}<div class="garage-grid"><section><div class="section-heading" style="margin-top:0"><h2>Your servers</h2><span class="badge live">Both connected</span></div>${['Club 01','Club 02'].map(name=>{const s=state.sessions.find(s=>s.server===name&&s.status==='live');return `<div class="server-line"><div class="row between"><h3>${name}</h3><span class="badge ${s?'live':''}">${s?'Running':'Ready'}</span></div><p>${s?e(s.name):'Available for your next session'}</p><button class="text-button" data-action="server-info" data-value="${name}">Connection details ${icon('arrow')}</button></div>`;}).join('')}<div class="section-heading"><h2>The club</h2></div><div class="server-line"><h3>People with the keys</h3><p>Admins configure the club. Hosts run sessions. Guests can watch.</p><button class="text-button" data-action="team">View access ${icon('arrow')}</button></div><div class="server-line"><h3>Your safety net</h3><p>Session history and your content stay on your server.</p><button class="text-button" data-action="backup">Backup & recovery ${icon('arrow')}</button></div></section><section><div class="section-heading" style="margin-top:0"><h2>Cars & tracks</h2>${btn(icon('plus')+' Add content','import','','compact')}</div>${Object.values(tracks).map(t=>`<div class="content-chip"><img src="${asset(t.image)}" alt="${e(t.name)}"><div><h3>${e(t.name)}</h3><p>${t.country} · Ready to use</p></div>${icon('check')}</div>`).join('')}${state.imported?'<div class="content-chip"><span class="setting-icon">'+icon('car')+'</span><div><h3>Weekend car pack</h3><p>6 cars · Sample import completed</p></div>'+icon('check')+'</div>':''}<div class="content-chip"><img src="${asset('silvia.jpg')}" alt="Nissan Silvia"><div><h3>Club drift cars</h3><p>6 cars · Liveries included</p></div>${icon('check')}</div><div class="section-heading"><h2>Streams & highlights</h2></div><div class="control-panel"><div class="row between"><b class="small">Simulators & cameras</b><span class="badge live">${watchState().sources.filter(x=>x.status==='live').length} connected</span></div><p class="small" style="margin-top:12px">Big drift runs are saved automatically. Connect each simulator once, then just drive.</p><button class="text-button" data-watch-action="setup">Set up streams ${icon('arrow')}</button><a class="text-button" href="#streams" style="margin-left:18px">Open live wall ${icon('screen')}</a></div></section></div>`;}
function welcome(){return `<div class="welcome-layout"><div class="welcome-art"><div><span class="eyebrow">THE BEST PART IS THE DRIVING</span><h2 style="margin-top:15px">Let’s get you<br>out there.</h2></div></div><section class="welcome-content"><div class="eyebrow accent">WELCOME TO PITLANE</div><h1>Your first session<br>starts here.</h1><p>Connect your Assetto Corsa installation. We’ll find your cars, tracks, and a home for your first session.</p><form data-form="connect"><label class="field">Assetto Corsa folder<input name="folder" placeholder="/corsa" value="/corsa" required><small>The folder on the server where Assetto Corsa is installed.</small></label><div class="step-line"><span>1</span><div>Connect your installation<p>Cars, tracks, and server settings are checked together.</p></div></div><div class="step-line"><span>2</span><div>Choose the driving<p>Drift, race, or practice. Your first session is ready-made.</p></div></div><div class="step-line"><span>3</span><div>Bring your people<p>One session, with everything they need to join.</p></div></div><button class="button primary full" type="submit">Find my cars & tracks ${icon('arrow')}</button><p class="quiet-note">Demo setup: the folder check and discovery are simulated.</p></form></section></div>`;}
function watch(id){return watchSession(id); }
function missing(){return `<div class="empty"><h1>This session has moved on.</h1><p>Pick another session to continue exploring.</p>${linkBtn('All sessions','sessions','primary')}</div>`;}
function render(){const [page,id]=(location.hash.slice(1)||'today').split('/');document.body.classList.toggle('watch-mode',page==='watch');main.classList.toggle('live-page',page==='live');main.classList.toggle('streams-page',page==='streams');document.querySelectorAll('.app-header nav a').forEach(a=>{const dest=a.hash.slice(1);const active=dest===page||(dest==='streams'&&page==='watch')||(dest==='sessions'&&['new','build','recap'].includes(page))||(dest==='drivers'&&page==='driver')||(dest==='today'&&page==='live');if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const pages={today,streams:liveStreams,new:newSession,build,sessions,drivers,driver:()=>profile(id),live:()=>live(id),recap:()=>recap(id),garage,welcome,watch:()=>watch(id)};main.innerHTML=(pages[page]||missing)();syncWatchAnimation();remember();}

function editDraft(kind){
  if(!draft)return;
  if(kind==='track')return modal('Where shall we drive?',`<p>Installed and ready. Grid capacity is checked as you choose.</p>${Object.entries(tracks).map(([id,t])=>`<button class="picker-item" data-action="select-track" data-value="${id}"><img src="${asset(t.image)}" alt=""><span><b>${e(t.name)}</b><small>${e(t.country)} · ${t.capacity} spaces</small></span>${icon(draft.track===id?'check':'arrow')}</button>`).join('')}`);
  if(kind==='cars')return modal('Bring the right cars.',`<p>Choose the kind of grid. Skins and individual slots are filled in for you.</p><form data-form="cars"><label class="field">Car collection<select name="cars">${['Club drift cars','BMW M3 Cup','Road cars'].map(c=>`<option ${c===draft.cars?'selected':''}>${c}</option>`).join('')}</select></label><label class="field">Drivers on the grid<input name="grid" type="number" min="1" max="24" value="${draft.grid}" required><small>${track(draft).name} has ${track(draft).capacity} spaces. You’ll see any mismatch before starting.</small></label><div class="dialog-actions">${btn('Cancel','close')}<button class="button primary" type="submit">Use this grid</button></div></form>`);
  if(kind==='format')return modal('How long shall we stay?',`<p>${draft.type==='Race'?'A race includes 10 minutes of practice and 10 minutes of qualifying. The remaining time is the race.':'One open session. Drivers can join at any time.'}</p><form data-form="format"><label class="field">Session length<select name="duration">${[30,45,60,90,120].map(n=>`<option value="${n}" ${n===Number(draft.duration)?'selected':''}>${n} minutes</option>`).join('')}</select></label><div class="dialog-actions">${btn('Cancel','close')}<button class="button primary">Set session length</button></div></form>`);
  if(kind==='weather')return modal('Set the mood.',`<p>Good visibility and predictable grip, by default.</p>${['Late afternoon','Clear midday'].map(w=>`<button class="picker-item" data-action="select-weather" data-value="${w}"><span class="setting-icon">${icon('sun')}</span><span><b>${w}</b><small>${w==='Late afternoon'?'Warm light · 16:00 · 22°C':'Bright and clear · 12:00 · 21°C'}</small></span>${icon(draft.weather===w?'check':'arrow')}</button>`).join('')}`);
  if(kind==='rules')return modal('Make everyone feel at home.',`<p>Pick a starting point. Rules belong to this session only.</p>${[['Friendly','Forgiving damage, optional assists, no pressure.'],['Factory assists','Authentic car assists, normal tyre and fuel use.'],['Full realism','No added assists, full damage, track limits on.']].map(([r,d])=>`<button class="picker-item" data-action="select-rules" data-value="${r}"><span><b>${r}</b><small>${d}</small></span>${icon(draft.rules===r?'check':'arrow')}</button>`).join('')}`);
}
function handover(id){modal('Who’s driving next?',`<p>Rig 01 · Nissan Silvia S14<br>Finish the current run before handing over. Existing results stay with ${e(person(state.seat).name.split(' ')[0])}.</p>${state.drivers.filter(d=>!d.live).map(d=>`<button class="driver-choice" data-action="assign" data-value="${d.id}">${avatar(d)}<span><b>${e(d.name)}</b><small>${d.visits} visits · Ready for a turn</small></span>${icon('arrow')}</button>`).join('')}<button class="text-button" data-action="new-handover">${icon('plus')} Someone new</button><div class="notice">Handovers affect new runs and highlights. Past scores are never silently reassigned.</div>`);}
function assign(id){finishSourceRecording('rig-01');const old=person(state.seat),next=person(id);old.live=false;next.live=true;next.session=old.session||'club';state.seat=id;state.feed.unshift(`${next.name} took over Rig 01 from ${old.name}.`);close();render();toast(`${next.name.split(' ')[0]} is at the wheel. New runs and clips are theirs.`);}
function launch(){const r=ready();if(!r.ok){render();return;}const id='session-'+(++state.demoIndex);const s={...draft,id,status:draft.when==='now'?'live':'planned',server:r.server,people:0,highlights:0,when:draft.when==='now'?'18:42':draft.when==='next'?'After current':draft.date.slice(11,16),date:draft.when==='next'?'2026-09-10T19:00':draft.date};state.sessions.unshift(s);draft=null;remember();if(s.status==='live'){go('live/'+id);toast(`${s.name} is on track. Invite your first driver.`);}else{go('today');toast(s.when==='After current'?`Added next on ${s.server}. The current session keeps running.`:`Scheduled for ${s.date.slice(0,10)} at ${s.when}, Oslo time.`);}}
function planned(id){const s=findSession(id);if(!s)return;modal(e(s.name),`<img class="preview-frame" src="${asset(track(s).image)}" alt="${e(track(s).name)}"><p>${e(track(s).name)} · ${e(s.type)} · ${s.duration} minutes</p><div class="summary-label"><span>Start</span><b>${e(s.when)} · ${e(s.date?.slice(0,10)||'Next')} · Oslo</b></div><div class="summary-label"><span>Server</span><b>${e(s.server)}</b></div><div class="readiness">Settings checked. ${s.grid} spaces ready. ${s.when==='After current'?'The current session finishes first.':'The server starts at the scheduled time.'}</div><div class="dialog-actions">${btn('Remove from plan','remove-plan',id)}${btn('Change time','reschedule',id,'primary')}</div>`);}

document.addEventListener('click',event=>{
  const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,value=el.dataset.value;
  switch(action){
    case 'skip':event.preventDefault();main.focus();break;
    case 'close':close();break;
    case 'experience':makeDraft(value);break;
    case 'edit':editDraft(value);break;
    case 'select-track':draft.track=value;close();render();break;
    case 'select-weather':draft.weather=value;close();render();break;
    case 'select-rules':draft.rules=value;close();render();break;
    case 'when':draft.when=value;render();break;
    case 'launch':launch();break;
    case 'reuse':close();makeDraft(findSession(value)?.type,findSession(value));break;
    case 'planned':planned(value);break;
    case 'remove-plan':state.sessions=state.sessions.filter(s=>s.id!==value);close();render();toast('Removed from the plan. Your other sessions stay as they were.');break;
    case 'reschedule':{const s=findSession(value);modal('Find a better time.',`<form data-form="reschedule" data-id="${value}"><label class="field">Start time · Europe/Oslo<input type="datetime-local" name="date" value="${e(s.date)}" min="2026-09-10T18:43" required></label><div class="error" role="alert"></div><div class="dialog-actions">${btn('Cancel','close')}<button class="button primary">Save new time</button></div></form>`);break;}
    case 'live-tab':state.tab=value;render();break;
    case 'filter':state.sessionFilter=value;render();break;
    case 'profile':go('driver/'+value);break;
    case 'handover':handover(value);break;
    case 'assign':assign(value);break;
    case 'new-handover':case 'add-driver':modal(action==='new-handover'?'A new face at the wheel.':'Make room for someone new.',`<p>A name is all you need. Their driving history grows from here.</p><form data-form="add-driver" data-handover="${action==='new-handover'}"><label class="field">Driver’s name<input name="name" placeholder="First and last name" maxlength="50" required autocomplete="off"></label><div class="error" role="alert"></div><div class="dialog-actions">${btn('Cancel','close')}<button class="button primary">${action==='new-handover'?'Add & hand over':'Add driver'}</button></div></form>`);break;
    case 'message':modal('A word from the pit.',`<p>Everyone in this session will see the message in game.</p><form data-form="message"><label class="field">Message to drivers<textarea name="message" placeholder="One more run, then we’ll switch drivers." required maxlength="220"></textarea></label><div class="error" role="alert"></div><div class="dialog-actions">${btn('Cancel','close')}<button class="button primary">Send to this session</button></div></form>`);break;
    case 'manage-drivers':modal('Everyone on track.',`<p>Remove a driver only when needed. They’ll be disconnected from this session.</p>${sessionDrivers(findSession(value)).map(d=>`<div class="driver-choice">${avatar(d)}<span style="flex:1"><b>${e(d.name)}</b><small>${e(d.car)}</small></span>${btn('Remove','kick',d.id,'compact')}</div>`).join('')}`);break;
    case 'kick':modal(`Remove ${e(person(value).name.split(' ')[0])}?`,`<p>This disconnects ${e(person(value).name)} from the session. Their existing results stay saved.</p><div class="dialog-actions">${btn('Keep driving','close')}${btn('Disconnect driver','confirm-kick',value,'danger')}</div>`);break;
    case 'confirm-kick':{const removed=person(value);const session=findSession(removed.session||'club');removed.live=false;if(session)session.people=Math.max(0,session.people-1);}close();render();toast('Driver disconnected in the demo. Existing results kept.');break;
    case 'phase':modal('Move the session along?',`<p>End ${e(state.phase.toLowerCase())} now and move every driver to ${state.phase==='Practice'?'qualifying':'the race'}.</p><div class="dialog-actions">${btn('Keep driving','close')}${btn('Move to next phase','confirm-phase',value,'primary')}</div>`);break;
    case 'confirm-phase':state.phase=state.phase==='Practice'?'Qualifying':'Race';close();render();toast(`Moved to ${state.phase.toLowerCase()} in the demo.`);break;
    case 'end':modal('Call it a good session?',`<p>All drivers will be disconnected. Results and highlights are already saved, ready for your recap.</p><div class="dialog-actions">${btn('Keep driving','close')}${btn('Finish & see recap','confirm-end',value,'primary')}</div>`);break;
    case 'confirm-end':{finishSessionCaptures(value);const s=findSession(value);s.results=sessionDrivers(s).map(d=>({...d}));sessionDrivers(s).forEach(d=>d.live=false);s.status='finished';s.when='Today, 18:42';state.feed.unshift(`${s.name} finished. Results and highlights saved.`);close();go('recap/'+value);toast('Session finished. The good bits are kept.');break;}
    case 'invite':modal('Get everyone onto the track.',`<p>One place for the session, the cars, and the track. Drivers see what they need before joining.</p><div class="control-panel"><span class="badge live">Driver view · preview</span><h3 style="margin:16px 0 8px">${e(findSession(value).name)}</h3><p class="small">${e(track(findSession(value)).name)} · ${e(findSession(value).cars)}</p><div class="check-row">${icon('check')}Track and car downloads together</div><div class="check-row">${icon('check')}Join link opens Content Manager</div><div class="check-row">${icon('check')}Any CSP requirements explained up front</div></div><p class="notice">Proposed join page. This concept has no public link or real game connection.</p><div class="dialog-actions">${btn('Got it','close','','primary')}</div>`);break;
    case 'highlight':modal('Nora found her flow.',`<p>24,680 points · A new personal best · Rudskogen</p><div class="clip-placeholder"><img class="preview-frame" src="${asset('silvia.jpg')}" alt="Nissan Silvia car preview used as a placeholder for Nora’s highlight"><span class="badge glass">STILL PREVIEW · NO VIDEO CONNECTED</span></div><div class="row between"><span class="small muted">Auto-saved to Nora’s profile</span><span class="badge">Best run of the session</span></div><p class="notice">In the real app, this opens the captured run from its connected recording source.</p><div class="dialog-actions">${btn(state.saved?'Saved to favourites':icon('plus')+' Keep as a favourite','save-highlight','','primary')}</div>`);break;
    case 'save-highlight':state.saved=true;close();remember();toast('Highlight added to favourites in this demo.');break;
    case 'first-use':go('welcome');break;
    case 'reset':state=initialState();draft=null;close();remember();go('today');toast('Demo reset. Ready for another lap.');break;
    case 'theme':{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';el.textContent=dark?'Day theme':'Night theme';el.setAttribute('aria-label',dark?'Switch to day theme':'Switch to night theme');break;}
    case 'notes':modal('One session. Start to finish.',`<p>Server Manager becomes a home for driving together. The session is the thing you create, run, watch, and remember.</p>${[['Today','What’s happening, what’s next, and one obvious way to start.'],['Sessions','Your plans, saved experiences, results, and highlights in one place.'],['Live','Every connected simulator, plus session views with cameras, positions, timing, and capture controls.'],['Drivers','People first. Shared simulators and Steam accounts attach to the same kind of profile.'],['Garage','Installation, content, servers, access, recordings, and backups. Setup once, then leave it alone.'],['The magic','Choose a driving style. Compatible defaults, grid checks, server allocation, and result capture happen underneath.']].map(([a,b])=>`<div class="definition-row"><b>${a}</b><p>${b}</p></div>`).join('')}<p class="notice">This is a proposal, with simulated data and operations. Public joining, safe driver handovers, and reliable one-action launches need backend work.</p>`);break;
    case 'server-info':modal(e(value)+' · behind the scenes',`<div class="readiness">Connected and ready. Ports have been assigned without conflicts.</div><div class="summary-label"><span>Engine</span><b>AssettoServer</b></div><div class="summary-label"><span>Install folder</span><b>/corsa</b></div><div class="summary-label"><span>Game UDP / TCP</span><b>${value==='Club 01'?'9600':'9604'}</b></div><div class="summary-label"><span>HTTP</span><b>${value==='Club 01'?'8081':'8082'}</b></div><details class="advanced"><summary>Advanced connection details</summary><p class="small">Telemetry uses local plugin ports. A real connection check must distinguish local readiness from internet reachability.</p></details><p class="notice">Example configuration. This prototype does not inspect or change your running servers.</p>`);break;
    case 'team':modal('People with the keys.',`<p>Access stays simple and follows the job.</p><div class="definition-row"><b>Admin</b><p>Set up the club, manage content, and operate all sessions.</p></div><div class="definition-row"><b>Host</b><p>Run sessions, switch drivers, and handle the grid.</p></div><div class="definition-row"><b>Viewer</b><p>Watch sessions and review results. No operating controls.</p></div><p class="notice">The mock shows an administrator’s view. “Host” maps to the existing steward role; this is not a permission change.</p>`);break;
    case 'backup':modal('Keep your club safe.',`<p>Backups should say exactly what they contain and when a restore takes effect.</p><div class="definition-row"><b>Settings</b><p>Accounts, sessions, rules, and server configuration.</p></div><div class="definition-row"><b>Content</b><p>Your installed car and track archives.</p></div><div class="definition-row"><b>Recordings</b><p>Show separately whether captured photos and clips are included.</p></div><p class="notice">Concept only. No backup is created or restored from this screen.</p>`);break;
    case 'recording':modal('Keep the good bits.',`<p>One clear recording status, with the technical settings underneath.</p><label class="toggle-line"><span>Save great drift runs<small>One clip per run. Keep the highest scores.</small></span><input type="checkbox" checked aria-label="Save great drift runs"></label><details class="advanced"><summary>Recording details</summary><div class="summary-label"><span>Source</span><b>Rig 01 · connected</b></div><div class="summary-label"><span>Clip length</span><b>15 seconds</b></div><div class="summary-label"><span>Minimum score</span><b>10,000 points</b></div><div class="summary-label"><span>Limit</span><b>12 clips per driver, per session</b></div></details><div class="dialog-actions">${btn('Done','save-recording','','primary')}</div>`);break;
    case 'save-recording':close();toast('Recording preference previewed. Real capture settings are unchanged.');break;
    case 'import':modal('More good things to drive.',`<p>Add a car pack or track. Type detection, extraction, and library refresh happen together.</p><div class="control-panel"><span class="setting-icon">${icon('car')}</span><h3 style="margin:15px 0 8px">Weekend car pack.zip</h3><p class="small">6 cars · 18 liveries · Sample archive</p></div><p class="notice">Try the sample to see the flow. No files will be uploaded, downloaded, or installed.</p><div class="dialog-actions">${btn('Cancel','close')}${btn('Import sample pack','import-demo','','primary')}</div>`);break;
    case 'import-demo':state.imported=true;close();render();toast('Sample import complete. 6 cars are ready for a session.');break;
    case 'export':{const s=findSession(value);const cells=[['Session','Driver','Best drift points','Best lap'],...sessionDrivers(s).map(d=>[s.name,d.name,d.score,d.lap])];const csv=cells.map(row=>row.map(c=>'"'+String(c).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='pitlane-demo-results.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Example results exported.');break;}
  }
});
document.addEventListener('submit',event=>{
  const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();const data=new FormData(form);
  switch(form.dataset.form){
    case 'cars':draft.cars=data.get('cars');draft.grid=Number(data.get('grid'));close();render();break;
    case 'format':draft.duration=Number(data.get('duration'));close();render();break;
    case 'add-driver':{const name=String(data.get('name')).trim();if(!name){form.querySelector('.error').textContent='Enter a name so scores have someone to belong to.';return;}const duplicate=state.drivers.find(d=>d.name.toLowerCase()===name.toLowerCase());if(duplicate){form.querySelector('.error').textContent='That driver is already in your club. Choose them from the list.';return;}const id='guest-'+(++state.demoIndex);state.drivers.push({id,name,initials:name.split(/\s+/).slice(0,2).map(n=>n[0]).join('').toUpperCase(),car:'Nissan Silvia S14',score:0,lap:'—',visits:0,guest:true,live:false});if(form.dataset.handover==='true')assign(id);else{close();render();toast(`${name} is part of the club.`);}break;}
    case 'message':{const message=String(data.get('message')).trim();if(!message){form.querySelector('.error').textContent='Write a message first.';return;}state.feed.unshift('Message to drivers: '+message);close();state.tab='activity';render();toast('Message shown in the simulated session.');break;}
    case 'reschedule':{const s=findSession(form.dataset.id);const date=String(data.get('date'));const start=new Date(date).getTime();if(!Number.isFinite(start)||start<=new Date('2026-09-10T18:42').getTime()){form.querySelector('.error').textContent='Choose a future time after the demo clock: 10 Sep, 18:42.';return;}const clash=state.sessions.some(other=>other.id!==s.id&&other.server===s.server&&other.status!=='finished'&&start<new Date(other.date||'2026-09-10T18:00').getTime()+other.duration*60000&&start+s.duration*60000>new Date(other.date||'2026-09-10T18:00').getTime());if(clash){form.querySelector('.error').textContent='That time overlaps another session on this server. Choose a later start.';return;}s.date=date;s.when=date.slice(11,16);close();render();toast('New start time saved in the demo.');break;}
    case 'connect':{const folder=String(data.get('folder')).trim();if(!folder)return;modal('Found. Checked. Ready.',`<div class="readiness"><div class="row">${icon('check')}Your first server is ready.</div><p>Sample discovery completed for ${e(folder)}.</p></div><div class="check-row">${icon('check')}Assetto Corsa server found</div><div class="check-row">${icon('check')}3 tracks and 6 club cars ready</div><div class="check-row">${icon('check')}A free set of ports selected</div><div class="check-row">${icon('check')}Friendly driving defaults prepared</div><p class="notice">Actual setup must also check credentials and lobby reachability before public joining. This is a simulated discovery.</p><div class="dialog-actions">${btn('Create my first session','start-first','','primary')}</div>`);break;}
  }
});
document.addEventListener('click',event=>{if(event.target.closest('[data-action="start-first"]')){state=initialState();state.sessions=[];state.onboarding=true;state.drivers.forEach(d=>d.live=false);close();remember();go('new');}});
document.addEventListener('change',event=>{const field=event.target.dataset.draft;if(field&&draft&&field!=='name'){draft[field]=event.target.type==='checkbox'?event.target.checked:event.target.value;render();}});
document.addEventListener('input',event=>{if(event.target.dataset.draft!=='name'||!draft)return;draft.name=event.target.value;remember();const r=ready();document.querySelector('.builder-summary h2').textContent=draft.name;document.querySelector('[data-action="launch"]').disabled=!r.ok;const panel=document.querySelector('#readiness');panel.classList.toggle('blocked',!r.ok);panel.innerHTML=`<div class="row">${icon(r.ok?'check':'info')}${r.ok?'Everything is ready':'One thing to sort out'}</div><p>${e(r.message)}</p>`;const status=document.querySelector('.heading-actions .small');status.className='small '+(r.ok?'green':'accent');status.innerHTML=icon(r.ok?'check':'info')+(r.ok?' All checked':' Check your setup');});
document.addEventListener('input',event=>{const kind=event.target.dataset.search;if(!kind)return;const query=event.target.value.toLowerCase();if(kind==='drivers'){document.querySelector('#driver-results').innerHTML=driverRows(state.drivers.filter(d=>d.name.toLowerCase().includes(query)));}else{state.query=event.target.value;document.querySelector('#session-results').innerHTML=state.sessions.filter(s=>(state.sessionFilter==='all'||s.status===state.sessionFilter)&&`${s.name} ${track(s).name} ${s.type}`.toLowerCase().includes(query)).map(sessionCard).join('')||'<div class="empty"><h2>No matching sessions.</h2><p>Try a different name or track.</p></div>';remember();}});
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)close();}});
window.addEventListener('hashchange',()=>{if(dialog.open)close();render();window.scrollTo(0,0);main.focus({preventScroll:true});});
render();
